// Catch the flies before the owl wakes up: tap a fly to catch it.
let goal = 8;
let caught = 0;
let over = false;
let timeLeft = 45;
const homes = {};

game.setGravity(0);
game.hud({ score: 0, timer: timeLeft, label: 'Catch ' + goal + ' flies' });
game.say('Shh, the owl is asleep. Tap the flies to catch them!');

for (const fly of game.find('fly')) homes[fly.id] = { x: fly.x, y: fly.y };

game.ask('How many flies can you catch?', ['Five', 'Eight']).then((index) => {
  goal = index === 0 ? 5 : 8;
  game.hud({ label: 'Catch ' + goal + ' flies' });
  game.say(goal === 5 ? 'Five flies. Quick fingers!' : 'Eight flies! Brave frog.');
});

// Each fly hovers around its home spot with a little wobble.
game.every(0.25, () => {
  for (const fly of game.find('fly')) {
    const home = homes[fly.id] || { x: fly.x, y: fly.y };
    homes[fly.id] = home;
    game.impulse(fly.id, {
      x: (home.x - fly.x) * 0.8 - fly.vx * 0.5 + (game.random() - 0.5) * 0.6,
      y: (home.y - fly.y) * 0.8 - fly.vy * 0.5 + (game.random() - 0.5) * 0.6,
    });
  }
});

game.on('tap', (e) => {
  if (over || !e.target || !e.target.tags.includes('fly')) return;
  caught += 1;
  game.remove(e.target.id);
  game.sound('pop');
  game.score(1);
  game.hud({ score: caught });
  if (caught >= goal) {
    over = true;
    game.celebrate('confetti');
    game.sound('tada');
    game.say('You caught them all, and the owl is still asleep!');
    game.win();
    return;
  }
  game.after(1.2, () => {
    if (over) return;
    const x = 2 + game.random() * 10;
    const y = 1.2 + game.random() * 3.5;
    const id = game.spawn('fly_1', { x: x, y: y, tags: ['fly'] });
    homes[id] = { x: x, y: y };
  });
});

game.every(1, () => {
  if (over) return;
  timeLeft -= 1;
  game.hud({ timer: timeLeft });
  if (timeLeft === 10) game.say('The owl is starting to stir...');
  if (timeLeft <= 0) {
    over = true;
    game.sound('buzz');
    game.say('Hoot! The owl woke up. Shall we try again?');
    game.lose();
  }
});
